import {
    Component,
    ElementRef,
    EventEmitter,
    Input,
    Output
} from '@angular/core';
import { WalletModel } from 'src/app/_models';

@Component({
    selector: 'app-dropdown-wallet',
    templateUrl: './dropdownWallet.component.html',
    styleUrls: ['./dropdownWallet.component.css']
})
export class DropdownWalletComponent {
    @Input() wallets: WalletModel[] = [];
    @Input() selectedWallet?: WalletModel;
    @Input() readonly: boolean = false;

    @Output() selectWalletEmitter = new EventEmitter<WalletModel>();

    showDropdown = false;
    dropdownNone = true;

    dropDownElement: HTMLElement | null = null;

    constructor(private elRef: ElementRef) {}

    ngOnInit() {
        this.dropDownElement =
            this.elRef.nativeElement.querySelector('#dropdownWallet');

        console.log(this.dropDownElement);
    }

    selectWallet(wallet: WalletModel) {
        this.showDropdown = false;
        this.selectedWallet = wallet;
        this.selectWalletEmitter.emit(wallet);
        if (!this.showDropdown) {
            setTimeout(() => {
                this.dropdownNone = true;
            }, 300);
        }
    }

    selectShowDropdown() {
        if (this.readonly) return;

        if (this.showDropdown)
            this.dropDownElement?.style.setProperty(
                '--height',
                this.dropDownElement?.clientHeight + 'px'
            );

        if (this.dropDownElement) {
            if (
                this.dropDownElement.clientHeight +
                    this.dropDownElement.getBoundingClientRect().top >
                window.innerHeight
            )
                this.dropDownElement?.style.setProperty('--top', '0px');
            else
                this.dropDownElement?.style.setProperty(
                    '--top',
                    'calc(100% - var(--height) - 10px)'
                );

			this.dropDownElement.style.setProperty('visibility', ' !important');
			this.dropDownElement.style.setProperty('display', 'block !important');
			this.dropDownElement.style.setProperty('visibility', 'visible');
        }

        this.dropdownNone = false;
        this.showDropdown = !this.showDropdown;
        if (!this.showDropdown) {
            setTimeout(() => {
                this.dropdownNone = true;
            }, 300);
        }
    }
}
<div class="custom-select default-input">
    <div class="selected-option" (click)="selectShowDropdown()">
        <span *ngIf="!selectedWallet">Select Wallet</span>
        <span *ngIf="selectedWallet"> {{ selectedWallet.name }} </span>
    </div>
    <div
		id="dropdownWallet"
        class="default-dropdown"
        [ngClass]="{
            'dropdown-show': showDropdown,
            'dropdown-hide': !showDropdown,
            'dropdown-display-none': !showDropdown && dropdownNone
        }"
    >
        <div
            class="default-dropdown-option"
            *ngFor="let wallet of wallets"
            (click)="selectWallet(wallet)"
        >
            <div>
                {{ wallet.name }}
            </div>
            <div class="sub-wallet-container">
                <div class="latest-transaction">21/12/2023 12:51</div>
                <div
                    [ngClass]="{
                        'income-amount': wallet.amount >= 0,
                        'expense-amount': wallet.amount < 0
                    }"
                    class="wallet-amount"
                >
                    {{ wallet.amount }} {{ wallet.currencyCode }}
                </div>
            </div>
        </div>
    </div>
</div>
